mapper.select:
SELECT A.*, B.USERNM, B.EMAIL FROM BOAD001T_TBL A
LEFT OUTER JOIN HABA920T_TBL B ON A.USERID = B.USERID AND A.CMPYCD = B.CMPYCD
WHERE UPPER(A.CMPYCD) = UPPER(#{cmpycd}) AND A.BOARDID = #{boardid}

mapper.insert:
INSERT INTO BOAD001T_TBL (
    cmpycd, fancode, subject, memo, userid, deptcd, filename, filesize,
    readcnt, commentcnt, reply_level, u_boardid, addtime, updtime, updemp
) VALUES (
    #{cmpycd}, #{fancode}, #{subject}, #{memo}, #{userid}, #{deptcd}, #{filename}, #{filesize},
    0, 0, 0, 0, NOW(), NOW(), #{userid}
)
